"""Demo: build the reduced Burau generators of B_4 and verify Artin's relations."""
from __future__ import annotations
import numpy as np


def burau(i: int, t: complex) -> np.ndarray:
    """Reduced Burau image of sigma_i in B_4 (i in {1,2,3}) at parameter t."""
    if i == 1:
        return np.array([[-t, 0, 0], [1, 1, 0], [0, 0, 1]], dtype=complex)
    if i == 2:
        return np.array([[1, t, 0], [0, -t, 0], [0, 1, 1]], dtype=complex)
    if i == 3:
        return np.array([[1, 0, 0], [0, 1, t], [0, 0, -t]], dtype=complex)
    raise ValueError("generator index must be 1, 2 or 3")


def verify(t: complex, tol: float = 1e-9) -> bool:
    s1, s2, s3 = burau(1, t), burau(2, t), burau(3, t)
    far = np.allclose(s1 @ s3, s3 @ s1, atol=tol)
    r12 = np.allclose(s1 @ s2 @ s1, s2 @ s1 @ s2, atol=tol)
    r23 = np.allclose(s2 @ s3 @ s2, s3 @ s2 @ s3, atol=tol)
    dets = all(abs(np.linalg.det(burau(i, t)) + t) < tol for i in (1, 2, 3))
    return far and r12 and r23 and dets


if __name__ == "__main__":
    for t in (-1.0, 2.0, 1j, 0.3 + 0.7j):
        print(f"t = {t}: representation of B_4 verified = {verify(t)}")

"""Demo: infinite order of W = rho(sigma_1 sigma_3) at t = -1 via unipotency."""
from __future__ import annotations
import numpy as np


def burau1(t: complex) -> np.ndarray:
    return np.array([[-t, 0, 0], [1, 1, 0], [0, 0, 1]], dtype=complex)


def burau3(t: complex) -> np.ndarray:
    return np.array([[1, 0, 0], [0, 1, t], [0, 0, -t]], dtype=complex)


def unipotent_order_test(max_n: int = 500) -> None:
    W = burau1(-1.0) @ burau3(-1.0)
    N = W - np.eye(3, dtype=complex)
    assert np.allclose(N @ N, 0), "N should be nilpotent of index 2"
    assert not np.allclose(N, 0), "N should be nonzero"
    seen = set()
    for n in range(max_n + 1):
        Wn = np.linalg.matrix_power(W, n)
        # closed form W^n = I + n N
        assert np.allclose(Wn, np.eye(3) + n * N)
        seen.add(round(Wn[1, 0].real))
    print(f"distinct (2,1) entries among W^0..W^{max_n}: {len(seen)} (all distinct)")
    print("=> W has infinite order; the braid image is infinite.")


if __name__ == "__main__":
    unipotent_order_test()

"""Demo: parameter dependence -- finite S_4 image at t=1 vs infinite image at t=-1."""
from __future__ import annotations
import numpy as np


def burau(i: int, t: complex) -> np.ndarray:
    mats = {
        1: [[-t, 0, 0], [1, 1, 0], [0, 0, 1]],
        2: [[1, t, 0], [0, -t, 0], [0, 1, 1]],
        3: [[1, 0, 0], [0, 1, t], [0, 0, -t]],
    }
    return np.array(mats[i], dtype=complex)


def involution_test(t: complex) -> bool:
    """True iff every generator squares to the identity at parameter t."""
    I = np.eye(3, dtype=complex)
    return all(np.allclose(burau(i, t) @ burau(i, t), I) for i in (1, 2, 3))


if __name__ == "__main__":
    print(f"t =  1: generators are involutions? {involution_test(1.0)}  -> S_4, finite")
    print(f"t = -1: generators are involutions? {involution_test(-1.0)} -> infinite image")

